import {
  OnboardingFlowView,
  ONBOARDING_REGISTRATION_COMPLETE_PATH,
  useOnboardingFlow,
  useOnboardingFlowApi,
  useOnboardingFlowState,
} from "@procertus-ui/ui-certification";
import { useEffect, useMemo } from "react";
import { Navigate, useNavigate, useSearchParams } from "react-router-dom";

import { findWegwijzerService } from "../wegwijzer/wegwijzer-services";

export { ONBOARDING_REGISTRATION_COMPLETE_PATH } from "@procertus-ui/ui-certification";

const WEGWIJZER_PATH = "/welcome";
const TRIAGE_PATH = (serviceId: string) => `/welcome/aanvraag/${serviceId}`;

/**
 * Formal onboarding after drafts exist. Expects ancestor {@link OnboardingFlowProvider}
 * ({@link PublicWelcomeOnboardingSessionLayout}).
 */
export function CustomerOnboardingFlow() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { redirectToRegistrationComplete, viewProps } = useOnboardingFlow({ navigate });
  const { flowState } = useOnboardingFlowState();
  const api = useOnboardingFlowApi();

  const svcParam = searchParams.get("service")?.trim() ?? "";
  useEffect(() => {
    if (!svcParam) return;
    const svc = findWegwijzerService(svcParam);
    api.setTrajectServiceId(svcParam, svc?.entry.label);
  }, [api, svcParam]);

  // Customer onboarding only runs once a certification request has been configured upstream
  // in the TrajectConfigureFlow. Without drafts there is nothing to onboard against.
  const hasDrafts = flowState.drafts.length > 0;

  useEffect(() => {
    if (!hasDrafts) return;
    if (flowState.step === "request") {
      api.goToOnboardingStep("origin");
    }
  }, [hasDrafts, flowState.step, api]);

  const cancelTarget = flowState.trajectServiceId
    ? TRIAGE_PATH(flowState.trajectServiceId)
    : WEGWIJZER_PATH;
  const cancelAction = useMemo(
    () => ({ label: "Annuleren", onClick: () => navigate(cancelTarget) }),
    [navigate, cancelTarget],
  );
  const isFirstStep = flowState.step === "origin";

  if (redirectToRegistrationComplete) {
    return <Navigate to={ONBOARDING_REGISTRATION_COMPLETE_PATH} replace />;
  }

  if (!hasDrafts) {
    return <Navigate to={WEGWIJZER_PATH} replace />;
  }

  if (flowState.step === "request") {
    return null;
  }

  return (
    <OnboardingFlowView
      {...viewProps}
      hideRequestStep
      backAction={isFirstStep ? undefined : viewProps.backAction}
      cancelAction={cancelAction}
    />
  );
}

import {
  OnboardingRequestStep,
  useOnboardingFlow,
  useOnboardingFlowApi,
  useOnboardingFlowState,
} from "@procertus-ui/ui-certification";
import { useEffect, useRef } from "react";
import { Navigate, useNavigate, useParams } from "react-router-dom";

import { useSyncOnboardingTrajectFromServiceId } from "../onboarding/use-sync-onboarding-traject-from-service-id";

const WEGWIJZER_PATH = "/welcome";
const TRIAGE_PATH = (serviceId: string) => `/welcome/aanvraag/${serviceId}`;

/**
 * Wizard-only step bundled with triage/start under {@link PublicWelcomeOnboardingSessionLayout}.
 */
export function TrajectConfigureFlow() {
  const navigate = useNavigate();
  const { serviceId } = useParams<{ serviceId: string }>();

  if (!serviceId) {
    return <Navigate to={WEGWIJZER_PATH} replace />;
  }

  return <TrajectConfigureFlowBody serviceId={serviceId} navigate={navigate} />;
}

function TrajectConfigureFlowBody({
  serviceId,
  navigate,
}: {
  serviceId: string;
  navigate: ReturnType<typeof useNavigate>;
}) {
  useSyncOnboardingTrajectFromServiceId(serviceId);
  const api = useOnboardingFlowApi();
  const { flowState } = useOnboardingFlowState();
  const { viewProps } = useOnboardingFlow({ navigate });
  const seenRequestStep = useRef(false);

  useEffect(() => {
    api.goToOnboardingStep("request");
  }, [api, serviceId]);

  useEffect(() => {
    if (flowState.step === "request") {
      seenRequestStep.current = true;
      return;
    }
    if (seenRequestStep.current) {
      navigate(TRIAGE_PATH(serviceId), { replace: true });
    }
  }, [flowState.step, navigate, serviceId]);

  return (
    <OnboardingRequestStep
      pageTitle={viewProps.certificationPhaseTitle}
      pageDescription={viewProps.certificationPhaseDescription}
      onSignInClick={viewProps.onSignInClick}
      certificationWizardProps={viewProps.certificationWizardProps}
    />
  );
}

